// 1. Obtener el string de texto del AI Agent
const jsonString = $input.item.json.output;

// 2. Parsear el string para convertirlo en un array
// (Ej: [ { "CampañaCL": "...", "CosteCL": "..." }, { ... } ])
const dataArray = JSON.parse(jsonString);

// 3. Crear un objeto vacío que contendrá todo
const finalObject = {};

// 4. Recorrer el array y fusionar cada objeto en el objeto principal
for (const item of dataArray) {
  // Object.assign() toma las claves/valores de 'item' 
  // y los copia en 'finalObject'
  Object.assign(finalObject, item);
}

// 5. Devolver un solo item que contiene el objeto fusionado
// La salida será 1 item con { "CampañaCL": "...", "CosteCL": "...", "CampañaLM": "...", ... }
return { json: finalObject };

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

// Separar la lista en 2 mitades: geocodificados y datos originales
const totalItems = items.length;
const mitad = totalItems / 2;

const geoItems = items.slice(0, mitad);
const originalItems = items.slice(mitad);

const output = [];

for (let i = 0; i < originalItems.length; i++) {
  const original = originalItems[i].json;
  const geoItem = geoItems[i]?.json || {};

  const location = geoItem.results?.[0]?.geometry?.location || {};
  const direccionGeo = geoItem.results?.[0]?.formatted_address || 'SIN_GEODIRECCION';

  output.push({
    json: {
      ...original,
      lat: location.lat || null,
      lng: location.lng || null,
      direccion_geocodificada: direccionGeo
    }
  });
}

return output;

function getColor(index) {
  const colors = [
    "ff0000ff", "ff00ff00", "ffff0000", "ff00ffff", "ffff00ff", "ffffff00",
    "ff9999ff", "ff99ff99", "ffff9999", "ff66ffff", "ffff66ff", "ffffff66",
    "ff6666ff", "ff66ff66", "ffff6666", "ff33ffff", "ffff33ff", "ffffff33"
  ];
  return colors[index % colors.length];
}

const rutas = {};
for (const punto of items) {
  const r = punto.json.ruta || "sin_ruta";
  if (!rutas[r]) rutas[r] = [];
  rutas[r].push(punto.json);
}

let styles = '';
let placemarks = '';

Object.entries(rutas).forEach(([rutaId, puntos], idx) => {
  const color = getColor(idx);
  const styleId = `ruta${rutaId}`;

  styles += `
  <Style id="${styleId}">
    <LineStyle>
      <color>${color}</color>
      <width>3</width>
    </LineStyle>
    <IconStyle>
      <color>${color}</color>
      <scale>1.1</scale>
      <Icon>
        <href>http://maps.google.com/mapfiles/kml/shapes/placemark_circle.png</href>
      </Icon>
    </IconStyle>
    <LabelStyle>
      <scale>0</scale> <!-- Oculta nombre en mapa -->
    </LabelStyle>
  </Style>`;

  const coords = puntos
    .sort((a, b) => a.orden - b.orden)
    .map(p => `${p.lng},${p.lat},0`)
    .join('\n');

  placemarks += `
  <Placemark>
    <name><![CDATA[Ruta ${rutaId}]]></name>
    <styleUrl>#${styleId}</styleUrl>
    <LineString>
      <tessellate>1</tessellate>
      <coordinates>${coords}</coordinates>
    </LineString>
  </Placemark>`;

  puntos.forEach((p) => {
    const nombre = p.CLIENTE || p.DIRECCION || p.ID?.toString() || 'SinNombre';
    placemarks += `
    <Placemark>
      <name><![CDATA[${nombre}]]></name>
      <styleUrl>#${styleId}</styleUrl>
      <Point>
        <coordinates>${p.lng},${p.lat},0</coordinates>
      </Point>
    </Placemark>`;
  });
});

const kml = `<?xml version="1.0" encoding="UTF-8"?>
<kml xmlns="http://www.opengis.net/kml/2.2">
<Document>
  <name>Rutas Bogotá</name>
  ${styles}
  ${placemarks}
</Document>
</kml>`;

return [{
  json: {},
  binary: {
    data: {
      data: Buffer.from(kml, 'utf8').toString('base64'),
      mimeType: 'application/vnd.google-earth.kml+xml',
      fileName: 'rutas_visual_kml.kml'
    }
  }
}];

const unique = {};
for (const item of items) {
  const id = item.json.ID;
  if (!unique[id]) {
    unique[id] = item;
  }
}
return Object.values(unique).map(i => ({ json: i.json }));

