const opts = {
  maxPorRuta: 25,        // capacidad por ruta
  maxIter: 15,           // iteraciones de Lloyd
  minPorRuta: 12,        // evita micro-rutas
  targetRadiusKm: 1.2,   // radio objetivo de cada ruta (compactación)
  mergeRadiusKm: 1.0,    // umbral para fusionar rutas pequeñas cercanas
  alphaRadio: 0.2,       // penalización por exceder el radio objetivo
  densidadRadioKm: 1.0,  // radio para calcular densidad local
  antiSolape: {
    targetRadiusKm: 1.0, // un poco más estricto ayuda a separar
    alphaRadio: 0.25,
    maxIterSolape: 60
  }
};

function agruparRutas(items, opts = {}) {
  // ===== Parámetros =====
  const maxPorRuta = opts.maxPorRuta ?? 25;
  const maxIter    = opts.maxIter ?? 15;
  const minPorRuta = opts.minPorRuta ?? 12;
  const targetRadiusKm = opts.targetRadiusKm ?? 1.2;
  const mergeRadiusKm  = opts.mergeRadiusKm ?? 1.0;
  const alphaRadio     = opts.alphaRadio ?? 0.15;
  const densidadRadioKm = opts.densidadRadioKm ?? 1.0;

  const antiSolapeCfg = {
    targetRadiusKm: opts.antiSolape?.targetRadiusKm ?? 1.0,
    alphaRadio: opts.antiSolape?.alphaRadio ?? 0.25,
    maxIterSolape: opts.antiSolape?.maxIterSolape ?? 60
  };

  // ===== Convertir entrada y sanitizar =====
  const puntos = (items || []).map((item, index) => ({
    lat: Number(item?.json?.lat),
    lng: Number(item?.json?.lng),
    index,
    data: item?.json ?? {}
  })).filter(p => Number.isFinite(p.lat) && Number.isFinite(p.lng));

  if (!puntos.length) throw new Error("No hay puntos válidos (lat/lng) para agrupar.");

  // ===== Haversine (km) =====
  const haversine = (lat1, lon1, lat2, lon2) => {
    const toRad = deg => deg * Math.PI / 180;
    const R = 6371;
    const dLat = toRad(lat2 - lat1);
    const dLon = toRad(lon2 - lon1);
    const a = Math.sin(dLat / 2) ** 2 +
              Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) *
              Math.sin(dLon / 2) ** 2;
    return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  };

  // ===== Densidad local =====
  const calcularDensidadPorPunto = (radioKm = densidadRadioKm) => {
    return puntos.map(p1 => {
      let cont = 0;
      for (const p2 of puntos) {
        if (haversine(p1.lat, p1.lng, p2.lat, p2.lng) < radioKm) cont++;
      }
      return { ...p1, densidad: cont };
    });
  };

  const puntosDensos = calcularDensidadPorPunto();
  const mediaDensidad = puntosDensos.reduce((s, p) => s + p.densidad, 0) / puntosDensos.length;

  const zonasAltas = puntosDensos.filter(p => p.densidad > mediaDensidad * 1.5);
  const zonasMedias = puntosDensos.filter(p => p.densidad > mediaDensidad * 0.8 && p.densidad <= mediaDensidad * 1.5);
  const zonasBajas  = puntosDensos.filter(p => p.densidad <= mediaDensidad * 0.8);

  const calcularClustersPorZona = (zona, factor) => {
    const count = zona.length;
    const capacidadEfectiva = Math.min(maxPorRuta, Math.max(6, Math.floor(maxPorRuta / factor)));
    return Math.max(1, Math.ceil(count / capacidadEfectiva));
  };

  const zonas = [
    { puntos: zonasAltas,  factor: 0.5 },
    { puntos: zonasMedias, factor: 1.2 },
    { puntos: zonasBajas,  factor: 1.6 }
  ];

  // ===== Utilidades K-Means con capacidad =====

  // k-means++ init
  function kmeansPlusPlusInit(puntos, k) {
    const cents = [];
    const pick = () => puntos[Math.floor(Math.random() * puntos.length)];
    cents.push(pick());
    while (cents.length < k) {
      const d2 = puntos.map(p => {
        let m = Infinity;
        for (const c of cents) {
          const d = haversine(p.lat, p.lng, c.lat, c.lng);
          if (d < m) m = d;
        }
        return m * m;
      });
      const sum = d2.reduce((a, b) => a + b, 0);
      const r = Math.random() * sum;
      let acc = 0, idx = 0;
      for (; idx < d2.length; idx++) { acc += d2[idx]; if (acc >= r) break; }
      cents.push(puntos[Math.min(idx, puntos.length - 1)]);
    }
    return cents.map(c => ({ lat: c.lat, lng: c.lng }));
  }

  // asignación con capacidad y penalización por radio
  function asignarConCapacidad(puntos, centroides, capacidad) {
    const asignacion = new Map();
    const contadores = Array(centroides.length).fill(0);

    const metas = puntos.map(p => {
      let best1 = { i: -1, d: Infinity }, best2 = { i: -1, d: Infinity };
      centroides.forEach((c, i) => {
        const d = haversine(p.lat, p.lng, c.lat, c.lng);
        if (d < best1.d) { best2 = best1; best1 = { i, d }; }
        else if (d < best2.d) { best2 = { i, d }; }
      });
      const gap = best2.d - best1.d;
      return { p, best1, best2, gap };
    });

    metas.sort((a, b) => b.gap - a.gap);

    for (const m of metas) {
      const tries = [m.best1, m.best2];
      let elegido = -1, costoMin = Infinity;

      for (const cand of tries) {
        if (cand.i === -1) continue;
        if (contadores[cand.i] >= capacidad) continue;

        const cluster = asignacion.get(cand.i) || [];
        let rMax = 0;
        for (const q of cluster) {
          const d = haversine(q.lat, q.lng, centroides[cand.i].lat, centroides[cand.i].lng);
          if (d > rMax) rMax = d;
        }
        const rNew = Math.max(rMax, cand.d);
        const penal = rNew > targetRadiusKm ? alphaRadio * (rNew - targetRadiusKm) : 0;

        const costo = cand.d + penal;
        if (costo < costoMin) { costoMin = costo; elegido = cand.i; }
      }

      if (elegido === -1) {
        let best = { i: -1, d: Infinity };
        centroides.forEach((c, i) => {
          if (contadores[i] < capacidad) {
            const d = haversine(m.p.lat, m.p.lng, c.lat, c.lng);
            if (d < best.d) best = { i, d };
          }
        });
        elegido = best.i;
      }

      if (elegido === -1) throw new Error("No hay capacidad en ningún cluster (ajusta k o parámetros).");

      if (!asignacion.has(elegido)) asignacion.set(elegido, []);
      asignacion.get(elegido).push(m.p);
      contadores[elegido]++;
    }
    return asignacion;
  }

  function recomputarCentroides(asignacion, centroides) {
    return centroides.map((c, i) => {
      const grupo = asignacion.get(i) || [];
      if (!grupo.length) return c;
      const lat = grupo.reduce((s, p) => s + p.lat, 0) / grupo.length;
      const lng = grupo.reduce((s, p) => s + p.lng, 0) / grupo.length;
      return { lat, lng };
    });
  }

  function localSwap(asignacion, centroides, capacidad) {
    let mejoro = false;
    const cont = centroides.map((_, i) => (asignacion.get(i) || []).length);
    for (let i = 0; i < centroides.length; i++) {
      const grupo = asignacion.get(i) || [];
      for (let gi = 0; gi < grupo.length; gi++) {
        const p = grupo[gi];
        const dA = haversine(p.lat, p.lng, centroides[i].lat, centroides[i].lng);
        let bestJ = -1, delta = 0;
        for (let j = 0; j < centroides.length; j++) {
          if (j === i) continue;
          if (cont[j] >= capacidad) continue;
          const dB = haversine(p.lat, p.lng, centroides[j].lat, centroides[j].lng);
          const clusterB = asignacion.get(j) || [];
          let rMax = 0;
          for (const q of clusterB) {
            const d = haversine(q.lat, q.lng, centroides[j].lat, centroides[j].lng);
            if (d > rMax) rMax = d;
          }
          const rNew = Math.max(rMax, dB);
          const penalB = rNew > targetRadiusKm ? alphaRadio * (rNew - targetRadiusKm) : 0;
          const mejora = dA - (dB + penalB);
          if (mejora > 0.05 && mejora > delta) { delta = mejora; bestJ = j; }
        }
        if (bestJ !== -1) {
          grupo.splice(gi, 1);
          asignacion.set(i, grupo);
          if (!asignacion.has(bestJ)) asignacion.set(bestJ, []);
          asignacion.get(bestJ).push(p);
          cont[i]--; cont[bestJ]++;
          mejoro = true;
        }
      }
    }
    return mejoro;
  }

  // ===== Clustering por zona con capacidad =====
  let salida = [];
  let clusterIdGlobal = 1;

  for (const { puntos: ptsZona, factor } of zonas) {
    if (!ptsZona.length) continue;

    const k = calcularClustersPorZona(ptsZona, factor);
    let centroides = kmeansPlusPlusInit(ptsZona, k);

    for (let iter = 0; iter < maxIter; iter++) {
      const asignacion = asignarConCapacidad(ptsZona, centroides, maxPorRuta);
      const nuevos = recomputarCentroides(asignacion, centroides);
      localSwap(asignacion, nuevos, maxPorRuta);

      const mov = nuevos.reduce((s, c, i) =>
        s + haversine(c.lat, c.lng, centroides[i].lat, centroides[i].lng), 0) / nuevos.length;

      centroides = nuevos;
      if (mov < 0.02) break; // ~20 m
    }

    const asignacionFinal = asignarConCapacidad(ptsZona, centroides, maxPorRuta);
    for (const [i, grupo] of asignacionFinal.entries()) {
      if (!grupo || !grupo.length) continue;
      for (const p of grupo) { p.ruta = clusterIdGlobal; salida.push(p); }
      clusterIdGlobal++;
    }
  }

  // ===== Post-proceso: fusionar rutas pequeñas y balancear =====
  const gruposPorRuta = {};
  for (const p of salida) {
    if (!gruposPorRuta[p.ruta]) gruposPorRuta[p.ruta] = [];
    gruposPorRuta[p.ruta].push(p);
  }

  let cambio = true;
  while (cambio) {
    cambio = false;
    const rutas = Object.keys(gruposPorRuta).map(Number);
    for (const ra of rutas) {
      const A = gruposPorRuta[ra];
      if (!A) continue;
      if (A.length >= minPorRuta) continue;

      const cA = A.reduce((acc, p) => ({ lat: acc.lat + p.lat, lng: acc.lng + p.lng }), { lat: 0, lng: 0 });
      cA.lat /= A.length; cA.lng /= A.length;

      let mejor = null;
      for (const rb of rutas) {
        if (rb === ra || !gruposPorRuta[rb]) continue;
        const B = gruposPorRuta[rb];
        const cB = B.reduce((acc, p) => ({ lat: acc.lat + p.lat, lng: acc.lng + p.lng }), { lat: 0, lng: 0 });
        cB.lat /= B.length; cB.lng /= B.length;
        const d = haversine(cA.lat, cA.lng, cB.lat, cB.lng);
        if (d <= mergeRadiusKm && (A.length + B.length) <= maxPorRuta) {
          if (!mejor || d < mejor.d) mejor = { rb, d };
        }
      }
      if (mejor) {
        gruposPorRuta[mejor.rb].push(...A);
        delete gruposPorRuta[ra];
        cambio = true;
      } else {
        const capacidades = Object.fromEntries(Object.entries(gruposPorRuta).map(([k, v]) => [k, v.length]));
        for (const p of A) {
          let best = null;
          for (const [rb, B] of Object.entries(gruposPorRuta)) {
            if (Number(rb) === ra) continue;
            if (capacidades[rb] >= maxPorRuta) continue;
            const cB = B.reduce((acc, q) => ({ lat: acc.lat + q.lat, lng: acc.lng + q.lng }), { lat: 0, lng: 0 });
            cB.lat /= B.length; cB.lng /= B.length;
            const d = haversine(p.lat, p.lng, cB.lat, cB.lng);
            if (!best || d < best.d) best = { rb, d };
          }
          if (best) { gruposPorRuta[best.rb].push(p); capacidades[best.rb]++; }
        }
        delete gruposPorRuta[ra];
        cambio = true;
      }
    }
  }

  // ======== Anti-solape por Convex Hulls ========
  // Utilidades geométricas (trabajan en lat/lng como plano local; suficiente a escala urbana)
  function orient(a,b,c){ return (b.lng-a.lng)*(c.lat-a.lat) - (b.lat-a.lat)*(c.lng-a.lng); }
  function onSeg(a,b,c){
    return Math.min(a.lat,b.lat) <= c.lat && c.lat <= Math.max(a.lat,b.lat) &&
           Math.min(a.lng,b.lng) <= c.lng && c.lng <= Math.max(a.lng,b.lng) &&
           Math.abs(orient(a,b,c)) < 1e-12;
  }
  function segInter(a,b,c,d){
    const o1 = Math.sign(orient(a,b,c)), o2 = Math.sign(orient(a,b,d));
    const o3 = Math.sign(orient(c,d,a)), o4 = Math.sign(orient(c,d,b));
    if (o1 !== o2 && o3 !== o4) return true;
    if (onSeg(a,b,c) || onSeg(a,b,d) || onSeg(c,d,a) || onSeg(c,d,b)) return true;
    return false;
  }
  function convexHull(pts){
    if (pts.length <= 2) return pts.slice();
    const P = pts.slice().sort((p,q)=> p.lng===q.lng ? p.lat-q.lat : p.lng-q.lng);
    const lower=[];
    for(const p of P){ while(lower.length>=2 && orient(lower[lower.length-2], lower[lower.length-1], p) <= 0) lower.pop(); lower.push(p); }
    const upper=[];
    for(let i=P.length-1;i>=0;i--){ const p=P[i]; while(upper.length>=2 && orient(upper[upper.length-2], upper[upper.length-1], p) <= 0) upper.pop(); upper.push(p); }
    upper.pop(); lower.pop();
    return lower.concat(upper);
  }
  function polyIntersects(A,B){
    if (!A.length || !B.length) return false;
    for(let i=0;i<A.length;i++){
      const a1=A[i], a2=A[(i+1)%A.length];
      for(let j=0;j<B.length;j++){
        const b1=B[j], b2=B[(j+1)%B.length];
        if (segInter(a1,a2,b1,b2)) return true;
      }
    }
    return false;
  }
  function centroide(pts){ return { lat: pts.reduce((s,p)=>s+p.lat,0)/pts.length, lng: pts.reduce((s,p)=>s+p.lng,0)/pts.length }; }
  function radioCluster(pts, c){ let r=0; for(const p of pts){ r=Math.max(r, haversine(p.lat,p.lng,c.lat,c.lng)); } return r; }

  function resolverSolapes(gruposPorRuta, params){
    const { maxPorRuta, targetRadiusKm, alphaRadio, maxIterSolape } = params;
    for (let iter=0; iter<maxIterSolape; iter++){
      const rutas = Object.keys(gruposPorRuta).map(Number);
      const hulls = {}, centros = {};
      for (const r of rutas){
        const pts = gruposPorRuta[r]; if (!pts || !pts.length) continue;
        hulls[r] = convexHull(pts);
        centros[r] = centroide(pts);
      }
      let par = null;
      outer:
      for (let i=0;i<rutas.length;i++){
        for (let j=i+1;j<rutas.length;j++){
          const ra=rutas[i], rb=rutas[j];
          if (!hulls[ra] || !hulls[rb]) continue;
          if (polyIntersects(hulls[ra], hulls[rb])) { par=[ra,rb]; break outer; }
        }
      }
      if (!par) break;

      const [ra, rb] = par;
      const A = gruposPorRuta[ra], B = gruposPorRuta[rb];
      const cA = centros[ra], cB = centros[rb];
      const candA = hulls[ra].slice(), candB = hulls[rb].slice();
      let mejorMovimiento = null;

      if (B.length < maxPorRuta) {
        for (const p of candA){
          const dA = haversine(p.lat,p.lng,cA.lat,cA.lng);
          const dB = haversine(p.lat,p.lng,cB.lat,cB.lng);
          const rB = radioCluster(B, cB);
          const rNew = Math.max(rB, dB);
          const penal = rNew > targetRadiusKm ? alphaRadio*(rNew-targetRadiusKm) : 0;
          const delta = dA - (dB + penal);
          if (!mejorMovimiento || delta > mejorMovimiento.delta){ mejorMovimiento = { from: ra, to: rb, p, delta }; }
        }
      }
      if (A.length < maxPorRuta) {
        for (const p of candB){
          const dB = haversine(p.lat,p.lng,cB.lat,cB.lng);
          const dA = haversine(p.lat,p.lng,cA.lat,cA.lng);
          const rA = radioCluster(A, cA);
          const rNew = Math.max(rA, dA);
          const penal = rNew > targetRadiusKm ? alphaRadio*(rNew-targetRadiusKm) : 0;
          const delta = dB - (dA + penal);
          if (!mejorMovimiento || delta > mejorMovimiento.delta){ mejorMovimiento = { from: rb, to: ra, p, delta }; }
        }
      }
