    longitud: String(lng),
    format_adress: formattedAddress,
    Cuidad: ciudad,
    'País': country,
  };
}

// ---- Intento 1: respuesta del nodo HTTP Request (geocode/json) ----
const firstResults = Array.isArray(input.results) ? input.results : [];
let best = pickBestResult(firstResults);

// ---- Intento 2 (fallback): geocode con minimalQuery ----
if (!best && prepData.queryMinimal && prepData.queryMinimal !== prepData.query) {
  try {
    const params = new URLSearchParams({
      address: prepData.queryMinimal,
      region: prepData.region || '',
      components: 'country:' + (prepData.isoCountryCode || ''),
      key: GOOGLE_KEY,
    });
    const resp = await fetch('https://maps.googleapis.com/maps/api/geocode/json?' + params.toString());
    const json = await resp.json();
    best = pickBestResult(json.results || []);
  } catch (e) { /* swallow and continue */ }
}

// ---- Intento 3 (fallback): findplacefromtext con query limpio + locationBias ----
if (!best) {
  try {
    const params = new URLSearchParams({
      input: prepData.query || prepData.queryMinimal || '',
      inputtype: 'textquery',
      fields: 'formatted_address,geometry',
      locationbias: prepData.locationBias || '',
      key: GOOGLE_KEY,
    });
    const resp = await fetch('https://maps.googleapis.com/maps/api/place/findplacefromtext/json?' + params.toString());
    const json = await resp.json();
    const candidate = Array.isArray(json.candidates) && json.candidates[0];
    if (candidate) {
      // Map candidate to result-like shape
      best = {
        geometry: candidate.geometry,
        formatted_address: candidate.formatted_address,
        address_components: [],
      };
    }
  } catch (e) { /* swallow and continue */ }
}

if (!best) {
  return [{
    json: {
      latitud: '',
      longitud: '',
      format_adress: '',
      Cuidad: detectedCity,
      'País': detectedCountry,
      error: 'No geocoding results',
    }
  }];
}

return [{ json: extractComponents(best) }];
